
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_b97_k_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_b97_k", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-2.438530042453612e+00, -2.397257747077995e+00, -2.339464584330448e+00, -2.259492898708392e+00, -2.150709331075924e+00, -2.006320988841580e+00, -1.821198370837643e+00, -1.594596412969060e+00, -1.330863051636273e+00, -1.028400222734206e+00, -6.764166750844020e-01, -4.232409949681429e-01, -3.725153221622571e-01, -3.111081194215291e-01, -2.296317116315884e-01, -1.502215956800867e-01, -6.835058875093349e-02, -1.497715224072010e-02, -2.182290379821869e-03, -1.819560045453192e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


